 {"id": "PEDS-C30-054", "sec": "Genetic associations", "page": 135, "q": "Match the syndrome with its cardiac defect — select the correct combination:", "pairs": [["Down syndrome", "supravalvular aortic stenosis + elfin facies"], ["Turner syndrome", "TOF + conotruncal"], ["Williams syndrome", "bicuspid aortic valve + coarctation"], ["DiGeorge syndrome", "endocardial cushion (AVSD)"]], "opts": ["A-4, B-2, C-3, D-1", "A-1, B-3, C-4, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1"], "ans": 2, "exp": "Correct pairs: Down syndrome→endocardial cushion (AVSD); Turner syndrome→bicuspid aortic valve + coarctation; Williams syndrome→supravalvular aortic stenosis + elfin facies; DiGeorge syndrome→TOF + conotruncal. (Book p135)", "type": "match"},
 {"id": "PEDS-C30-055", "sec": "Maternal associations", "page": 135, "q": "The teratogenic drug associated with Ebstein's anomaly is —", "opts": ["Phenytoin", "Alcohol", "Warfarin", "Lithium"], "ans": 3, "exp": "Teratogens: a. lithium → Ebstein's anomaly (Book p135)", "type": "mcq"},
