 {"id": "PEDS-C30-057", "sec": "Maternal associations", "page": 135, "q": "Match the maternal factor with the fetal defect — select the correct combination:", "pairs": [["Rubella", "Most common cyanotic CHD"], ["Diabetes", "Most common CHD"], ["VSD", "TGA (most specific)"], ["TGA", "PDA + PS + VSD"]], "opts": ["A-4, B-1, C-2, D-3", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-3, B-1, C-4, D-2"], "ans": 2, "exp": "Correct pairs: Rubella→PDA + PS + VSD; Diabetes→TGA (most specific); VSD→Most common CHD; TGA→Most common cyanotic CHD. (Book p135)", "type": "match"},
 {"id": "PEDS-C30-058", "sec": "Maternal associations", "page": 135, "stem": "A newborn of a mother treated with lithium during pregnancy has a holosystolic murmur; echocardiography shows apical displacement of the tricuspid valve leaflets.", "q": "The associated defect is —", "opts": ["Tetralogy of Fallot", "Coarctation of the aorta", "Ebstein's anomaly", "Atrio-ventricular septal defect"], "ans": 2, "exp": "Lithium exposure in pregnancy → Ebstein's anomaly (Book p135)", "type": "case"},
 {"id": "PEDS-C30-059", "sec": "NADA's criteria", "page": 135, "q": "In NADA's criteria, the diagnosis of CHD requires 1 major or ___ minor criteria.", "opts": ["3", "4", "5", "2"], "ans": 3, "exp": "Diagnosis: presence of 1 major OR 2 minor criteria (Book p135)", "type": "fill"},
 {"id": "PEDS-C30-060", "sec": "NADA's criteria", "page": 135, "q": "A major criterion in NADA's criteria is a systolic murmur of —", "opts": ["≥ grade 3", "< grade 3", "≥ grade 1", "≥ grade 4 only"], "ans": 0, "exp": "Major: systolic murmur ≥ grade 3 (Book p135)", "type": "mcq"},
 {"id": "PEDS-C30-061", "sec": "NADA's criteria", "page": 135, "q": "Any diastolic murmur in NADA's criteria is a —", "opts": ["Laboratory criterion", "Major criterion", "Minor criterion", "Exclusion criterion"], "ans": 1, "exp": "Major: any diastolic murmur (Book p135)", "type": "mcq"},
 {"id": "PEDS-C30-062", "sec": "NADA's criteria", "page": 135, "q": "Central cyanosis qualifies as a major criterion only when —", "opts": ["It is peripheral acrocyanosis", "It is present with a normal SpO₂", "There is no improvement on O₂ inhalation", "It improves on O₂ inhalation"], "ans": 2, "exp": "Major: central cyanosis with no improvement on O₂ inhalation (Book p135)", "type": "mcq"},
 {"id": "PEDS-C30-063", "sec": "NADA's criteria", "page": 135, "q": "If cyanosis improves on O₂ inhalation, the etiology is likely —", "opts": ["Cardiac", "Hematological", "Neurological", "Respiratory"], "ans": 3, "exp": "Improvement on O₂ → respiratory etiology (Book p135)", "type": "mcq"},
 {"id": "PEDS-C30-064", "sec": "NADA's criteria", "page": 135, "q": "The fourth major criterion in NADA's criteria is —", "opts": ["Features of congestive cardiac failure (CCF)", "A systolic murmur of less than grade 3", "An abnormal ECG with right axis deviation", "An abnormal S3 with normal blood pressure"], "ans": 0, "exp": "Major 4: features of congestive cardiac failure (CCF) (Book p135)", "type": "mcq"},
 {"id": "PEDS-C30-065", "sec": "NADA's criteria", "page": 135, "q": "A systolic murmur of less than grade 3 in NADA's criteria is a —", "opts": ["Imaging criterion", "Minor criterion", "Major criterion", "Exclusion criterion"], "ans": 1, "exp": "Minor: systolic murmur < grade 3 (Book p135)", "type": "mcq"},
 {"id": "PEDS-C30-066", "sec": "NADA's criteria", "page": 135, "q": "Which of the following is a minor criterion in NADA's criteria?", "opts": ["Systolic murmur ≥ grade 3", "Features of CCF", "Abnormal S3", "Any diastolic murmur"], "ans": 2, "exp": "Minor criteria: systolic murmur < grade 3, abnormal BP, abnormal ECG, abnormal X-ray, abnormal S3 (Book p135)", "type": "mcq"},
 {"id": "PEDS-C30-067", "sec": "NADA's criteria", "page": 135, "q": "Which of the following is NOT a minor criterion in NADA's criteria?", "opts": ["Abnormal ECG", "Abnormal X-ray", "Abnormal BP", "Any diastolic murmur"], "ans": 3, "exp": "Any diastolic murmur is a MAJOR criterion; ECG, X-ray and BP are minor (Book p135)", "type": "mcq"},
 {"id": "PEDS-C30-068", "sec": "NADA's criteria", "page": 135, "q": "Any diastolic murmur is a minor criterion in NADA's criteria.", "opts": ["True", "False"], "ans": 1, "exp": "False — any diastolic murmur is a MAJOR criterion (Book p135)", "type": "tf"},
